package org.deeptimeline.app
import java.io.File
import java.io.RandomAccessFile
import java.nio.ByteBuffer
import java.nio.ByteOrder
import java.nio.channels.FileChannel
import kotlin.math.floor
class TimezoneRaster(file:File):AutoCloseable{private val handle=RandomAccessFile(file,"r");private val channel=handle.channel;private val buffer:ByteBuffer=channel.map(FileChannel.MapMode.READ_ONLY,0,channel.size()).order(ByteOrder.BIG_ENDIAN);private val width:Int;private val height:Int;private val indexOffset:Int;private val runsOffset:Int;private val names:List<String>;init{require(channel.size()>=32){"Timezone data header is incomplete"};require(buffer.get(0).toInt()==66&&buffer.get(1).toInt()==80&&buffer.get(2).toInt()==84&&buffer.get(3).toInt()==90){"Timezone data signature is invalid"};require(u16(4)==1){"Unsupported timezone dataset version"};width=buffer.getInt(8);height=buffer.getInt(12);val count=u16(16);val namesOffset=buffer.getInt(20);indexOffset=buffer.getInt(24);runsOffset=buffer.getInt(28);require(width>0&&height>0&&count in 1..3000&&namesOffset>=32&&indexOffset>namesOffset&&runsOffset>indexOffset&&runsOffset.toLong()<channel.size()){ "Timezone dataset offsets are invalid" };val cursor=buffer.duplicate().order(ByteOrder.BIG_ENDIAN);cursor.position(namesOffset);val list=ArrayList<String>(count);repeat(count){val size=cursor.short.toInt() and 65535;require(size in 1..128&&cursor.position()+size<=indexOffset){"Timezone palette is invalid"};val bytes=ByteArray(size);cursor.get(bytes);list.add(String(bytes,Charsets.UTF_8))};names=list;require(runsOffset.toLong()>=indexOffset.toLong()+height*4L){"Timezone row index is invalid"}};private fun u16(at:Int)=buffer.getShort(at).toInt() and 65535;fun lookup(latitude:Double,longitude:Double):String?{require(latitude.isFinite()&&longitude.isFinite()&&latitude in -90.0..90.0&&longitude in -180.0..180.0){"Coordinates are invalid"};val lat=latitude.coerceIn(-90.0,90.0);val lon=longitude.coerceIn(-180.0,180.0);val row=floor((90.0-lat)/180.0*height).toInt().coerceIn(0,height-1);val column=floor((lon+180.0)/360.0*width).toInt().coerceIn(0,width-1);val rowStart=buffer.getInt(indexOffset+row*4).toLong() and 4294967295L;var offset=runsOffset.toLong()+rowStart;require(offset in runsOffset.toLong() until channel.size()){ "Timezone row points outside dataset" };val cursor=buffer.duplicate().order(ByteOrder.BIG_ENDIAN);cursor.position(offset.toInt());var x=0;while(x<width){var run=0;var shift=0;while(true){require(cursor.remaining()>2&&shift<=28){"Timezone run is malformed"};val byte=cursor.get().toInt() and 255;run=run or ((byte and 127) shl shift);if(byte and 128==0)break;shift+=7};require(run in 1..width-x&&cursor.remaining()>=2){"Timezone run length is malformed"};val code=cursor.short.toInt() and 65535;if(column<x+run)return if(code==65535)null else names.getOrNull(code)?:throw IllegalStateException("Timezone palette index invalid");x+=run};return null};override fun close(){channel.close();handle.close()}}
